#include <map>
#include <string>
#include <iostream>

// Custom stateful comparator
struct StringLengthLess {
    bool operator()(const std::string& a, const std::string& b) const {
        return a.length() < b.length();
    }
};

int main() {
    // Type definition uses the custom comparator type
    using LenMap = std::map<std::string, int, StringLengthLess>;

    // The comparator object (default constructed) is used implicitly
    LenMap coll;
    coll["b"] = 1; 
    coll["aaa"] = 2; 
    coll["cc"] = 3;

    // Iteration order based on length: "b", "cc", "aaa"
}
